1:# Design
12:## OfficeFloor REST endpoints — routes MUST live under `rest/api/`
25:## OfficeFloor REST endpoints
42:### Worked example — `PUT /owners/{ownerId}`
49:# First step runs first. Validate before Load so an invalid body is a 400,
50:# not masked by a 404 for a missing owner.
118:### Step wiring
131:### Function parameters
143:### Passing state between steps — `Out<T>` / `@Val`
154:### Naming
164:### Request body and validation
173:### Transactions
179:### Errors
187:### Security
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { QuickAddBar } from './QuickAddBar';
import { ShowRetired, useShowRetired } from './ShowRetired';
import { useSheetToday } from '../sheet/useSheet';
import { GRADES, gradeOn, peopleKey, usePeople, type Person } from './usePeople';

/** The sheet's people: one form to add a person or edit the one whose editor is open, and the list. */
function PeoplePanel({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data: everyone = [] } = usePeople(sheet);
  // Retired people have no row unless they are shown; their claims still count in every total.
  const [showRetired] = useShowRetired();
  const people = showRetired ? everyone : everyone.filter((p) => !p.retired);
  const [editing, setEditing] = useState<number | null>(null);
  // The version of the person the editor loaded: a save is refused if someone saved since.
  const [version, setVersion] = useState(0);
  const [name, setName] = useState('');
  const [grade, setGrade] = useState<string>('A');
  // The date the form's grade is in force from; blank for the sheet's today.
  const [gradeFrom, setGradeFrom] = useState('');
  const today = useSheetToday(sheet);
  const [blank, setBlank] = useState(false);
  const base = `/api/sheets/${encodeURIComponent(sheet)}/people`;

  const submitOnce = useSubmitOnce();
  const save = useMutation({
    mutationFn: (p: { id: number | null; name: string; grade: string; gradeFrom: string; version: number }) =>
      p.id === null
        ? postJson<Person>(base, { name: p.name, grade: p.grade, gradeFrom: p.gradeFrom, user })
        : putJson<Person>(`${base}/${p.id}`, { name: p.name, grade: p.grade, gradeFrom: p.gradeFrom, version: p.version, user }),
    onError: async (e) => {
      // Someone else saved this person since the editor loaded it: the form shows what is stored
      // now (and that version), and the list is re-read so a fresh editor loads it too.
      if (e instanceof HttpError && e.status === 409 && e.body) {
        const current = JSON.parse(e.body) as Person;
        setName(current.name);
        setGrade(gradeOn(current, today));
        setVersion(current.version);
        await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      }
    },
    onSuccess: async () => {
      setEditing(null);
      setName('');
      setGrade('A');
      setGradeFrom('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
    },
  });

  // An error goes as soon as its form is changed or submitted again, or an editor is opened.
  const clearError = () => {
    save.reset();
    setBlank(false);
  };

  const open = (p: Person) => {
    clearError();
    setEditing(p.id);
    setVersion(p.version);
    setName(p.name);
    setGrade(gradeOn(p, today));
    setGradeFrom('');
  };
  const cancel = () => {
    clearError();
    setEditing(null);
    setName('');
    setGrade('A');
    setGradeFrom('');
  };

  return (
    <section data-testid="people-panel">
      <h2>People</h2>
      <form
        data-testid="person-form"
        onSubmit={(e) => {
          e.preventDefault();
          if (name.trim() === '') {
            // Refused here, before anything is sent: the store and the audit file are untouched.
            save.reset();
            setBlank(true);
            return;
          }
          setBlank(false);
          submitOnce(() => save.mutateAsync({ id: editing, name, grade, gradeFrom: gradeFrom.trim(), version }));
        }}
      >
        <label>
          Name{' '}
          <input
            data-testid="person-form-name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <label>
          Grade{' '}
          <select
            data-testid="person-form-grade"
            value={grade}
            onChange={(e) => {
              setGrade(e.target.value);
              clearError();
            }}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="person-form-grade-from"
            placeholder={today || 'yyyy-mm-dd'}
            value={gradeFrom}
            onChange={(e) => {
              setGradeFrom(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add' : 'Save'}
        </button>
        {editing !== null && (
          <>
            {' '}
            <button type="button" data-testid="person-form-cancel" onClick={cancel}>
              Cancel
            </button>
          </>
        )}
        {(blank || save.isError) && (
          <span data-testid="person-form-error" role="alert">
            {' '}
            {blank
              ? 'A name is required.'
              : save.error instanceof HttpError && save.error.status === 409
                ? 'Someone else saved this person since you opened it; the form now shows what is stored.'
                : 'Could not save this person.'}
          </span>
        )}
      </form>
      <QuickAddBar user={user} sheet={sheet} />
      <ShowRetired />
      <table data-testid="people-list">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <th />
            <PersonColumns.Slot user={user} sheet={sheet} />
          </tr>
        </thead>
        <tbody>
          {people.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{gradeOn(p, today)}</td>
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
                  Edit
                </button>
              </td>
              <PersonCells.Slot user={user} sheet={sheet} person={p} />
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 10, Component: PeoplePanel });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** `version` counts the person's saves; an edit sends the version it loaded, so a save made by
 *  someone else in the meantime refuses it. `statementCount` is how many statements have been
 *  taken for them; `statedTotal` the last one's due-total (two decimals, null when it was n/a or
 *  none was taken) and `statementDate` its date (yyyy-mm-dd, null when none was taken).
 *  `retired` is whether a retirement date is set (whatever the date), `retiredFrom` that date
 *  (yyyy-mm-dd, null when not retired). `held` is whether they are on hold: their OPEN claims then
 *  count in no live total. `patrons` are the ids of the people they have named as patrons, in
 *  the order they were named. `grade` is the grade in force on the sheet's today when they were read;
 *  `grades` every grade recorded, by from-date (null: from the beginning of time, first). */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: { grade: string; from: string | null }[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  held: boolean;
  patrons: number[];
};

export const GRADES = ['A', 'B', 'C'] as const;

export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'] as const;

/** The sheet's people in the order they were added, re-read whenever the sheet is loaded. */
export function usePeople(sheet: string) {
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    staleTime: 0,
    gcTime: 0,
  });
}

/** The person's grade in force on `date` (yyyy-mm-dd): the one from the latest date on or before
 *  it, the first one they were given applying from the beginning of time. */
export function gradeOn(person: Person, date: string): string {
  let found = person.grades[0]?.grade ?? person.grade;
  for (const g of person.grades) if (g.from === null || g.from <= date) found = g.grade;
  return found;
}
import { asFlag, useSearchParam } from '../../url/useSearchParam';

/** Whether retired people are listed. Off when the screen is first opened; kept in the URL, so
 *  loading a sheet leaves it as it is. */
export function useShowRetired() {
  return useSearchParam('retired', asFlag);
}

/** The "show retired" toggle above the people list. */
export function ShowRetired() {
  const [on, setOn] = useShowRetired();
  return (
    <label>
      <input
        type="checkbox"
        data-testid="show-retired"
        checked={on}
        onChange={(e) => setOn(e.target.checked ? true : undefined)}
      />{' '}
      Show retired
    </label>
  );
}
import { defineSlot } from '../Slot';

/**
 * The shell's nav bar. Every page contributes its own link — the shell never lists the pages.
 * A nav link carries `data-testid="nav-<section>"` (the test contract; CLAUDE.md).
 */
export const AppNav = defineSlot('app.nav');
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/usePeople';

/** Extra column headers of the people list, one `<th>` per contribution. */
export const PersonColumns = defineSlot<{ user: string; sheet: string }>('person.columns');

/**
 * Extra cells of a person's row, one `<td>` per contribution, in the same order as their
 * PersonColumns headers. Everything kept per person (claims, ...) shows here, inside the row.
 */
export const PersonCells = defineSlot<{ user: string; sheet: string; person: Person }>('person.cells');
import { defineSlot } from '../Slot';

/**
 * The active sheet's content on the home screen. Rendered only once someone is signed in and a
 * sheet is loaded; everything kept per sheet contributes a panel here, keyed by `sheet`.
 */
export const SheetPanels = defineSlot<{ user: string; sheet: string }>('sheet.panels');

